package com.sirithree.shopops.admin.benchmark.v1.dataset.stage5;
import static org.assertj.core.api.Assertions.assertThat; import java.util.Set; import java.util.stream.Collectors; import org.junit.jupiter.api.Test;
class IdempotencyHeldOutIsolationTest { @Test void heldOutRootsAreNewAndReservedOnlyForTest() throws Exception { Set<String> testRoots=Stage5IdempotencyDatasetSupport.cases().stream().filter(v->v.split().equals("test")).map(v->v.benchmarkCase().semanticRootId).collect(Collectors.toSet()); assertThat(testRoots).hasSize(4).isEqualTo(Stage5IdempotencyDatasetSupport.testExclusiveRoots()); assertThat(Stage5IdempotencyDatasetSupport.cases().stream().filter(v->v.split().equals("test"))).allSatisfy(v->{ assertThat(v.benchmarkCase().reservedForHeldOut).isTrue(); assertThat(v.benchmarkCase().tags).contains("HELD_OUT"); }); }}
